Description: This Terraform configuration creates an AWS Route 53 public hosted zone and defines a Route 53 Traffic Policy for an `A` record. The traffic policy uses weighted routing to split traffic evenly between two IPv4 endpoints. A Route 53 Traffic Policy Instance is then created to publish the policy as `app.example.com`.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region used for provider operations. Route 53 is global, but the AWS provider still requires a region."
  type        = string
  default     = "us-east-1"
}

variable "domain_name" {
  description = "Domain name for the Route 53 hosted zone."
  type        = string
  default     = "example.com"
}

variable "record_name" {
  description = "DNS record name managed by the Route 53 traffic policy."
  type        = string
  default     = "app.example.com"
}

variable "endpoint_one_ip" {
  description = "First IPv4 endpoint for weighted routing."
  type        = string
  default     = "203.0.113.10"
